DECLARE @start_time DATETIME2 = SYSUTCDATETIME();
DECLARE @trace_id VARCHAR(100) = CONCAT('TRC-', FORMAT(@start_time, 'yyyyMMdd-HHmmss'));
DECLARE @total_rows BIGINT = 0;
DECLARE @status VARCHAR(20) = 'SUCCESS';
DECLARE @error_msg NVARCHAR(MAX) = '';

BEGIN TRY
    -- Execute 13 Distributed CTAS Replications
    IF OBJECT_ID('dbo.dim_date', 'U') IS NOT NULL DROP TABLE dbo.dim_date;
    CREATE TABLE dbo.dim_date AS SELECT * FROM SmartFarming_Lakehouse.gold.dim_date;

    IF OBJECT_ID('dbo.dim_facility', 'U') IS NOT NULL DROP TABLE dbo.dim_facility;
    CREATE TABLE dbo.dim_facility AS SELECT * FROM SmartFarming_Lakehouse.gold.dim_facility;

    IF OBJECT_ID('dbo.dim_zone', 'U') IS NOT NULL DROP TABLE dbo.dim_zone;
    CREATE TABLE dbo.dim_zone AS SELECT * FROM SmartFarming_Lakehouse.gold.dim_zone;

    IF OBJECT_ID('dbo.dim_equipment', 'U') IS NOT NULL DROP TABLE dbo.dim_equipment;
    CREATE TABLE dbo.dim_equipment AS SELECT * FROM SmartFarming_Lakehouse.gold.dim_equipment;

    IF OBJECT_ID('dbo.dim_crop', 'U') IS NOT NULL DROP TABLE dbo.dim_crop;
    CREATE TABLE dbo.dim_crop AS SELECT * FROM SmartFarming_Lakehouse.gold.dim_crop;

    IF OBJECT_ID('dbo.dim_technician', 'U') IS NOT NULL DROP TABLE dbo.dim_technician;
    CREATE TABLE dbo.dim_technician AS SELECT * FROM SmartFarming_Lakehouse.gold.dim_technician;

    IF OBJECT_ID('dbo.fact_environmental_daily', 'U') IS NOT NULL DROP TABLE dbo.fact_environmental_daily;
    CREATE TABLE dbo.fact_environmental_daily AS SELECT * FROM SmartFarming_Lakehouse.gold.fact_environmental_daily;

    IF OBJECT_ID('dbo.fact_equipment_telemetry', 'U') IS NOT NULL DROP TABLE dbo.fact_equipment_telemetry;
    CREATE TABLE dbo.fact_equipment_telemetry AS SELECT * FROM SmartFarming_Lakehouse.gold.fact_equipment_telemetry;

    IF OBJECT_ID('dbo.fact_crop_yield', 'U') IS NOT NULL DROP TABLE dbo.fact_crop_yield;
    CREATE TABLE dbo.fact_crop_yield AS SELECT * FROM SmartFarming_Lakehouse.gold.fact_crop_yield;

    IF OBJECT_ID('dbo.fact_irrigation_daily', 'U') IS NOT NULL DROP TABLE dbo.fact_irrigation_daily;
    CREATE TABLE dbo.fact_irrigation_daily AS SELECT * FROM SmartFarming_Lakehouse.gold.fact_irrigation_daily;

    IF OBJECT_ID('dbo.fact_lighting_dli_daily', 'U') IS NOT NULL DROP TABLE dbo.fact_lighting_dli_daily;
    CREATE TABLE dbo.fact_lighting_dli_daily AS SELECT * FROM SmartFarming_Lakehouse.gold.fact_lighting_dli_daily;

    IF OBJECT_ID('dbo.fact_maintenance_sla', 'U') IS NOT NULL DROP TABLE dbo.fact_maintenance_sla;
    CREATE TABLE dbo.fact_maintenance_sla AS SELECT * FROM SmartFarming_Lakehouse.gold.fact_maintenance_sla;

    IF OBJECT_ID('dbo.fact_dead_letter_governance', 'U') IS NOT NULL DROP TABLE dbo.fact_dead_letter_governance;
    CREATE TABLE dbo.fact_dead_letter_governance AS SELECT * FROM SmartFarming_Lakehouse.gold.fact_dead_letter_governance;

    -- Dynamic Row Sum across all 13 tables
    SELECT @total_rows = SUM(cnt) FROM (
        SELECT COUNT(*) AS cnt FROM dbo.dim_date
        UNION ALL SELECT COUNT(*) FROM dbo.dim_facility
        UNION ALL SELECT COUNT(*) FROM dbo.dim_zone
        UNION ALL SELECT COUNT(*) FROM dbo.dim_equipment
        UNION ALL SELECT COUNT(*) FROM dbo.dim_crop
        UNION ALL SELECT COUNT(*) FROM dbo.dim_technician
        UNION ALL SELECT COUNT(*) FROM dbo.fact_environmental_daily
        UNION ALL SELECT COUNT(*) FROM dbo.fact_equipment_telemetry
        UNION ALL SELECT COUNT(*) FROM dbo.fact_crop_yield
        UNION ALL SELECT COUNT(*) FROM dbo.fact_irrigation_daily
        UNION ALL SELECT COUNT(*) FROM dbo.fact_lighting_dli_daily
        UNION ALL SELECT COUNT(*) FROM dbo.fact_maintenance_sla
        UNION ALL SELECT COUNT(*) FROM dbo.fact_dead_letter_governance
    ) AS row_summary;

END TRY
BEGIN CATCH
    SET @status = 'FAILED';
    SET @error_msg = ERROR_MESSAGE();
END CATCH;

DECLARE @end_time DATETIME2 = SYSUTCDATETIME();
DECLARE @duration_ms BIGINT = DATEDIFF(millisecond, @start_time, @end_time);

-- Log dynamically measured execution span
INSERT INTO SmartFarming_Lakehouse.gold.fact_dataops_pipeline_log (
    TraceId, SpanId, PipelineName, StageName, Component,
    ExecutionStatus, SourceRowCount, TargetRowCount,
    ExecutionDurationMs, ErrorMessage, Timestamp
)
VALUES (
    @trace_id, 'SPN-WHCTAS', 'Pipeline_Medallion_Batch_Orchestration',
    'Warehouse_CTAS_Sync', 'Synapse_Warehouse',
    @status, @total_rows, @total_rows,
    @duration_ms, @error_msg, @end_time
);
